import{_ as a,o as e,a as s,b as l}from"./app.C41L12d5.js";const i="/ascendc.github.io/assets/zh-cn_formulaimage_0000002353015644.BEr9F2Hj.png",c="/ascendc.github.io/assets/zh-cn_formulaimage_0000002386692741.D_vTm8QE.png",u=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"高阶API","link":"/api/SIMD-API/adv_api/adv_api"},{"text":"数学计算","link":"/api/SIMD-API/adv_api/math_compute/math_compute"},{"text":"Fma接口","link":"/api/SIMD-API/adv_api/math_compute/Fma_interface/Fma_interface"},{"text":"Fma","link":"/api/SIMD-API/adv_api/math_compute/Fma_interface/Fma"}]},"headers":[],"relativePath":"api/SIMD-API/adv_api/math_compute/Fma_interface/Fma.md","filePath":"api/SIMD-API/adv_api/math_compute/Fma_interface/Fma.md","outlineHeaders":[{"level":2,"title":"产品支持情况","slug":"产品支持情况","link":"#产品支持情况"},{"level":2,"title":"功能说明","slug":"功能说明","link":"#功能说明"},{"level":2,"title":"函数原型","slug":"函数原型","link":"#函数原型"},{"level":2,"title":"参数说明","slug":"参数说明","link":"#参数说明"},{"level":2,"title":"返回值说明","slug":"返回值说明","link":"#返回值说明"},{"level":2,"title":"约束说明","slug":"约束说明","link":"#约束说明"},{"level":2,"title":"调用示例","slug":"调用示例","link":"#调用示例"}],"lastUpdated":1787132628000}'),r={name:"api/SIMD-API/adv_api/math_compute/Fma_interface/Fma.md"};function n(o,t,d,h,p,m){return e(),s("div",null,[...t[0]||(t[0]=[l('<div><article class="markdown-body"><h1>Fma</h1><h2 id="产品支持情况">产品支持情况<a class="header-anchor" href="#产品支持情况">​</a></h2><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT：支持</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品：不支持</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品：不支持</li></ul></div><div data-filter="310b"><ul><li>Atlas 200I/500 A2 推理产品：不支持</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品AI Core：不支持</li><li>Atlas 推理系列产品Vector Core：不支持</li></ul></div><div data-filter="910"><ul><li>Atlas 训练系列产品：不支持</li></ul></div><h2 id="功能说明">功能说明<a class="header-anchor" href="#功能说明">​</a></h2><p>按元素计算两个输入相乘后与第三个输入相加的结果。计算公式如下：</p><p><img src="'+i+'" alt></p><p><img src="'+c+`" alt></p><h2 id="函数原型">函数原型<a class="header-anchor" href="#函数原型">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入临时空间</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;const FmaConfig&amp; config = DEFAULT_FMA_CONFIG, typename T&gt;
__aicore__ inline void Fma(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;T&gt;&amp; src1,const LocalTensor&lt;T&gt;&amp; src2, const LocalTensor&lt;uint8_t&gt;&amp; sharedTmpBuffer, const uint32_t count)
</code></pre></div></li><li><p>接口框架申请临时空间</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>template &lt;const FmaConfig&amp; config = DEFAULT_FMA_CONFIG, typename T&gt;
__aicore__ inline void Fma(const LocalTensor&lt;T&gt;&amp; dst, const LocalTensor&lt;T&gt;&amp; src0, const LocalTensor&lt;T&gt;&amp; src1, const LocalTensor&lt;T&gt;&amp; src2, const uint32_t count)
</code></pre></div></li></ul><p>由于该接口的内部实现中涉及精度转换。需要额外的临时空间来存储计算过程中的中间变量。临时空间支持开发者<strong>通过sharedTmpBuffer入参传入</strong>和<strong>接口框架申请</strong>两种方式。</p><ul><li>通过sharedTmpBuffer入参传入，使用该tensor作为临时空间进行处理，接口框架不再申请。该方式开发者可以自行管理sharedTmpBuffer内存空间，并在接口调用完成后，复用该部分内存，内存不会反复申请释放，灵活性较高，内存利用率也较高。</li><li>接口框架申请临时空间，开发者无需申请，但是需要预留临时空间的大小。</li></ul><p>通过sharedTmpBuffer传入的情况，开发者需要为tensor申请空间；接口框架申请的方式，开发者需要预留临时空间。临时空间大小BufferSize的获取方式如下：通过<a href="GetFmaMaxMinTmpSize.html">GetFmaMaxMinTmpSize</a>中提供的接口获取需要预留空间的大小。</p><h2 id="参数说明">参数说明<a class="header-anchor" href="#参数说明">​</a></h2><p><strong>表1</strong> 模板参数说明</p><table><thead><tr><th>参数名</th><th>描述</th></tr></thead><tbody><tr><td>FmaConfig</td><td>Fma算法的相关配置。此参数可选配，FmaConfig类型，具体定义如下方代码所示，其中参数的含义为：<br><br>isReuseSource：是否允许修改源操作数。该参数预留，传入默认值false即可。</td></tr><tr><td>T</td><td>操作数的数据类型。支持的数据类型为：half、float。</td></tr></tbody></table><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>struct FmaConfig {
    bool isReuseSource;
};
</code></pre></div><p><strong>表2</strong> 接口参数说明</p><table><thead><tr><th>参数名</th><th>输入/输出</th><th>描述</th></tr></thead><tbody><tr><td>dst</td><td>输出</td><td>目的操作数。<br><br>类型为<a href="../../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。</td></tr><tr><td>src0、src1、src2</td><td>输入</td><td>源操作数。<br><br>类型为<a href="../../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。<br><br>源操作数的数据类型需要与目的操作数保持一致。</td></tr><tr><td>sharedTmpBuffer</td><td>输入</td><td>临时缓存。<br><br>类型为<a href="../../../basic_api/data_structures/LocalTensor/LocalTensor.html">LocalTensor</a>，支持的TPosition为VECIN/VECCALC/VECOUT。<br><br>用于Fma内部复杂计算时存储中间变量，由开发者提供。<br><br>临时空间大小BufferSize的获取方式请参考<a href="GetFmaMaxMinTmpSize.html">GetFmaMaxMinTmpSize</a>。</td></tr><tr><td>count</td><td>输入</td><td>参与计算的元素个数。</td></tr></tbody></table><h2 id="返回值说明">返回值说明<a class="header-anchor" href="#返回值说明">​</a></h2><p>无</p><h2 id="约束说明">约束说明<a class="header-anchor" href="#约束说明">​</a></h2><ul><li><strong>不支持源操作数与目的操作数地址重叠。</strong></li><li>不支持sharedTmpBuffer与源操作数和目的操作数地址重叠。</li><li>操作数地址对齐要求请参见<a href="../../../general_description_and_constraints.html#section796754519912">通用地址对齐约束</a>。</li></ul><h2 id="调用示例">调用示例<a class="header-anchor" href="#调用示例">​</a></h2><ul><li><p>通过sharedTmpBuffer入参传入</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>AscendC::TPipe pipe;
AscendC::TQue&lt;AscendC::TPosition::VECCALC, 1&gt; tmpQue;
pipe.InitBuffer(tmpQue, 1, bufferSize); // bufferSize通过Host侧tiling参数获取
AscendC::LocalTensor&lt;uint8_t&gt; sharedTmpBuffer = tmpQue.AllocTensor&lt;uint8_t&gt;();
// 输入tensor长度为1024,算子输入的数据类型为half,实际计算个数为512
static constexpr AscendC::FmaConfig fmaConfig = {false}; // 不修改源操作数
// dst、src0、src1、src2为half类型的LocalTensor
AscendC::Fma&lt;fmaConfig, half&gt;(dst, src0, src1, src2, sharedTmpBuffer, 512);
</code></pre></div></li><li><p>接口框架申请临时空间</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>AscendC::TPipe pipe;
AscendC::TQue&lt;AscendC::TPosition::VECCALC, 1&gt; tmpQue;
pipe.InitBuffer(tmpQue, 1, bufferSize); // bufferSize通过Host侧tiling参数获取
// 输入tensor长度为1024,算子输入的数据类型为half,实际计算个数为512
static constexpr AscendC::FmaConfig fmaConfig = {false}; // 不修改源操作数
// dst、src0、src1、src2为half类型的LocalTensor
AscendC::Fma&lt;fmaConfig, half&gt;(dst, src0, src1, src2, 512);
</code></pre></div></li></ul><p>结果示例如下：</p><div class="code-block"><div class="code-header"><span class="lang-label">Text</span><button class="copy-btn" title="复制代码"><svg width="16" height="16" viewBox="0 0 16 16"><path d="M0 6.75C0 5.784.784 5 1.75 5h1.5a.75.75 0 0 1 0 1.5h-1.5a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-1.5a.75.75 0 0 1 1.5 0v1.5A1.75 1.75 0 0 1 9.25 16h-7.5A1.75 1.75 0 0 1 0 14.25Z"></path><path d="M5 1.75C5 .784 5.784 0 6.75 0h7.5C15.216 0 16 .784 16 1.75v7.5A1.75 1.75 0 0 1 14.25 11h-7.5A1.75 1.75 0 0 1 5 9.25Zm1.75-.25a.25.25 0 0 0-.25.25v7.5c0 .138.112.25.25.25h7.5a.25.25 0 0 0 .25-.25v-7.5a.25.25 0 0 0-.25-.25Z"></path></svg></button></div><pre class="highlight"><code>输入数据(src0):[1 1 1 ...... 1 1 1]
输入数据(src1):[2 2 2 ...... 2 2 2]
输入数据(src2):[1 1 1 ...... 1 1 1]
输出数据(dst):[3 3 3 ...... 3 3 3]
</code></pre></div></article></div>`,1)])])}const f=a(r,[["render",n]]);export{u as __pageData,f as default};
